use blit_core::job_log::{open_log, Event, EventBody, LogLine, Outcome, Role, RunInfo, RunStart, Summary, VERSION, FORMAT};
use blit_core::job_record::LogRead;
use blit_core::remote::transfer::RemoteTransferProgress;
use blit_core::run_log::{End, LogPlace, RunLog, RunTotals};
use std::path::PathBuf;

fn line(seq: u64, body: EventBody) -> LogLine {
    LogLine::Event(Event { ts_ms: seq + 10, seq, body })
}

#[tokio::main(flavor = "current_thread")]
async fn main() {
    let id = "41414141414141414141414141414141";
    let place = LogPlace { dir: PathBuf::from("overlapping"), participant: "fixture".into(), keep: 20, finished: None };
    let log = RunLog::new(Some(place), id);
    log.start(Role::Initiator, RunInfo::default(), None);
    let reporter = RemoteTransferProgress::audit_only(log.audit_lane_at(End::Receiving).unwrap());
    reporter.report_file_failed("queued".into(), "fixture".into()).await;
    let totals = || Some(RunTotals { files_failed: 1, ..Default::default() });
    let first = log.close(Outcome::Failed, None, totals());
    tokio::pin!(first);
    tokio::select! {
        biased;
        _ = &mut first => panic!("the open sender should keep close pending"),
        _ = std::future::ready(()) => {}
    }
    let second = log.close(Outcome::Failed, None, totals()).await.unwrap();
    drop(reporter);
    let mut failures = 0;
    let mut marker = None;
    for event in open_log(second.path.as_deref().unwrap()).unwrap().map(|line| line.unwrap()) {
        if let LogLine::Event(e) = event {
            match e.body {
                EventBody::FileFailed { .. } => failures += 1,
                EventBody::Summary(s) => marker = Some(s.all_events_logged),
                _ => {}
            }
        }
    }
    println!("overlapping close: queued 1, read {failures}, marker {marker:?}, report.complete {}, first returns None {}", second.complete, first.await.is_none());
    let start = RunStart { format: FORMAT.into(), version: VERSION, run_id: id.into(), participant: "fixture".into(), role: Role::Destination, attempt: 1, host: "".into(), build: "".into(), run: RunInfo::default()};
    let mut read = LogRead::default();
    read.begin_log();
    read.read_line(line(0, EventBody::RunStart(Box::new(start))));
    read.read_line(line(1, EventBody::Summary(Summary { all_events_logged:true, ..Default::default() })));
    read.read_line(line(2, EventBody::RunEnd { outcome: Outcome::Ok, detail: None }));
    read.read_line(line(3, EventBody::FileFailed { path: "extra".into(), reason: "fixture".into(), raw: None, left_in_place: Some(false) }));
    println!("after end and extra event, complete before end_log {}", read.complete());
    read.end_log();
    println!("same stream, complete after end_log {}", read.complete());
}
