use blit_core::copy::{create_regular_within, Within};
use std::fs;
use std::os::unix::fs::symlink;
use std::path::Path;
fn main() {
    for (aliased, existing) in [(39, false), (40, false), (42, true)] {
        let tmp = Path::new("core-link-cases").join(format!("{aliased}-{existing}"));
        let dst = tmp.join("dst");
        fs::create_dir_all(&dst).unwrap();
        let dst = fs::canonicalize(dst).unwrap();
        let leaf = dst.join("leaf");
        if existing { fs::write(&leaf, b"existing bytes").unwrap(); }
        let mut link = leaf.clone();
        for n in 0..aliased {
            let here = dst.parent().unwrap().join(format!("alias{n}"));
            symlink(link, &here).unwrap();
            link = here;
        }
        let entry = dst.join("entry");
        symlink(link, &entry).unwrap();
        let system = fs::metadata(&entry).map(|m| m.len()).map_err(|e| e.raw_os_error());
        let opened = create_regular_within(&entry, Some(&Within::hold(&dst))).map(|_| ()).map_err(|e| e.to_string());
        println!("total links {}, existing {existing}, system {:?}, blit {:?}, leaf len {:?}", aliased + 1, system, opened, fs::metadata(leaf).map(|m| m.len()).ok());
    }
}
