use blit_core::job_log::{open_log, EventBody, LogLine, Outcome, Role, RunInfo};
use blit_core::remote::transfer::RemoteTransferProgress;
use blit_core::run_log::{End, LogPlace, RunLog, RunTotals};
use std::path::PathBuf;

#[tokio::main(flavor = "current_thread")]
async fn main() {
    let log = RunLog::new(Some(LogPlace { dir: PathBuf::from("lanes"), participant: "fixture".into(), keep: 20, finished: None }), "41494149414941494149414941494149");
    log.start(Role::Initiator, RunInfo::default(), None);
    let first_lane = log.audit_lane_at(End::Receiving).unwrap();
    let mut first_close = Box::pin(log.close(Outcome::Failed, None, Some(RunTotals::default())));
    tokio::select! {
        biased;
        _ = &mut first_close => panic!("the first lane is still held"),
        _ = std::future::ready(()) => {}
    }
    let other = log.clone();
    std::thread::spawn(move || {
        let second_runtime = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
        second_runtime.block_on(async {
            let second_lane = RemoteTransferProgress::audit_only(other.audit_lane_at(End::Receiving).unwrap());
            second_lane.report_file_failed("second lane file".into(),"fixture".into()).await;
        });
    }).join().unwrap();
    drop(first_close);
    drop(first_lane);
    let report = log.close(Outcome::Failed, None, Some(RunTotals { files_failed: 1, ..Default::default() })).await.unwrap();
    let mut events = 0;
    let mut evidence = None;
    for item in open_log(report.path.as_deref().unwrap()).unwrap() {
        if let Ok(LogLine::Event(event)) = item {
            match event.body {
                EventBody::FileFailed {..} => events += 1,
                EventBody::Summary(s) => evidence = Some(s.all_events_logged),
                _ => {}
            }
        }
    }
    println!("new lane while close was pending, one queued failure; close cancelled, retried: file events {events}, summary {evidence:?}, report.complete {}",report.complete);
}
